ARR1 = np.array([-5.5, 3.0])
ARR2 = np.array([[-5.5, 3.0], [1.0, 2.0]])
ARR3 = np.array([True, False])


@patch(target="os.getcwd", new=ARR1)
def test_patch_array_new():
